export type GenesisSpecificEditorial = {
  context: string;
  formation: string;
  textual: string;
  bibliography: string[];
};

const W1='Wenham, Gordon J., Genesis 1–15, Word Biblical Commentary 1, Word Books, 1987.';
const W2='Wenham, Gordon J., Genesis 16–50, Word Biblical Commentary 2, Word Books, 1994.';
const WEST1='Westermann, Claus, Genesis 1–11: A Commentary, Augsburg/Fortress, 1984.';
const WEST2='Westermann, Claus, Genesis 12–36: A Commentary, Augsburg/Fortress, 1985.';
const WEST3='Westermann, Claus, Genesis 37–50: A Commentary, Augsburg/Fortress, 1986.';
const SARNA='Sarna, Nahum M., Genesis, JPS Torah Commentary, Jewish Publication Society, 1989.';
const H1='Hamilton, Victor P., The Book of Genesis, Chapters 1–17, NICOT, Eerdmans, 1990.';
const H2='Hamilton, Victor P., The Book of Genesis, Chapters 18–50, NICOT, Eerdmans, 1995.';
const CARR='Carr, David M., The Formation of Genesis 1–11: Biblical and Other Precursors, Oxford University Press, 2020.';
const CARRF='Carr, David M., Reading the Fractures of Genesis, Westminster John Knox, 1996.';
const BLUM='Blum, Erhard, Die Komposition der Vätergeschichte, Neukirchener Verlag, 1984.';
const BADEN='Baden, Joel S., The Composition of the Pentateuch, Yale University Press, 2012.';
const SCHMID='Schmid, Konrad, Genesis and the Moses Story, Eisenbrauns, 2010.';

export const genesisEditorialSpecific: Record<number, GenesisSpecificEditorial> = {
1:{context:'Gen 1,1–2,3 presuppone una cosmologia antica nella quale cielo, terra, acque e luminari appartengono a un universo ordinato per sfere e funzioni. I paralleli mesopotamici, soprattutto le tradizioni cosmogoniche babilonesi, illuminano il vocabolario culturale condiviso, ma il testo biblico opera una forte riconfigurazione: sole e luna non sono divinità, il cosmo non nasce da una lotta fra dèi e l’umanità intera riceve dignità di immagine divina. Il sabato costituisce il vertice teologico dell’ordine creato.',formation:'La lingua, la struttura numerica, le formule di esecuzione e approvazione, l’interesse per separazioni, benedizione, fecondità e sabato collocano Gen 1,1–2,3 nel materiale sacerdotale. La datazione precisa di P resta discussa, ma la forma del racconto riflette un’elaborazione scribale matura. La sua collocazione davanti al racconto non sacerdotale di Gen 2–3 crea intenzionalmente una doppia apertura della Genesi: cosmica e antropologica.',textual:'MT, LXX e Pentateuco Samaritano concordano nell’impianto generale. Le questioni principali sono soprattutto esegetico-sintattiche: il valore di bereshit in 1,1, il rapporto fra 1,1 e 1,2 e la resa di ruach elohim. In 1,14–18 la terminologia evita i nomi comuni di sole e luna, dato letterariamente significativo più che variante testuale. Nessuna variante maggiore autorizza a ricostruire un racconto della creazione sostanzialmente diverso.',bibliography:[W1,WEST1,CARR,SARNA]},
2:{context:'Gen 2,4b–25 descrive l’origine umana con immagini di suolo, irrigazione, giardino, lavoro e parentela. Il giardino possiede affinità con immagini regali e templari del Vicino Oriente antico, ma non è localizzabile geograficamente attraverso i quattro fiumi come se fosse una carta moderna. Il racconto riflette un’antropologia relazionale: adam proviene da adamah, riceve il soffio vitale e trova nella donna un aiuto “corrispondente”, non subordinato per definizione.',formation:'Gen 2,4a chiude normalmente l’unità sacerdotale precedente; 2,4b apre una narrazione non-P con diverso stile, ordine creativo e uso di YHWH Elohim. L’antica attribuzione a J resta influente nella storia della ricerca, ma molti studi contemporanei preferiscono parlare di racconto non sacerdotale e di successive espansioni. La forma finale accosta Gen 1 e Gen 2 senza armonizzarli, invitando a leggerli come prospettive complementari ma letterariamente distinte.',textual:'Il testo ebraico è nel complesso stabile, ma alcuni termini sono rari e difficili: ed in 2,6 può indicare una corrente o umidità; tsela in 2,21–22 significa normalmente “lato/fianco” e la tradizionale “costola” è una specificazione interpretativa. La LXX rende tali difficoltà secondo la propria comprensione. Le varianti non eliminano la differenza strutturale fra questo racconto e Gen 1.',bibliography:[W1,WEST1,CARR,CARRF]},
3:{context:'Gen 3 utilizza motivi sapienziali ed eziologici per spiegare esperienza del limite, vergogna, dolore, conflitto e mortalità. Il serpente appartiene al mondo simbolico del racconto e il testo ebraico non lo identifica con Satana; tale identificazione nasce nella storia successiva della ricezione. L’albero della vita e figure di custodia del giardino trovano analogie nell’immaginario del Vicino Oriente antico, ma sono integrate in una riflessione specificamente israelita sulla relazione con Dio.',formation:'Il capitolo continua il racconto non-P iniziato in 2,4b. Tensioni interne e possibili ampliamenti sono discussi, ma l’unità narrativa fondamentale lega comando, trasgressione, interrogatorio, sentenze ed espulsione. Nella forma finale Gen 3 dialoga con Gen 1: l’umanità creata per governare responsabilmente sperimenta ora un governo deformato dal desiderio e dalla rottura delle relazioni.',textual:'La trasmissione è relativamente stabile. In 3,15 il testo ebraico parla della discendenza della donna e del serpente; la lettura cristologica tradizionale appartiene alla ricezione canonica e teologica, non a una variante che trasformi il senso grammaticale originario. La Vulgata ha avuto un ruolo importante nella storia interpretativa del versetto. Altre differenze fra MT e versioni sono perlopiù minori.',bibliography:[W1,WEST1,CARR,SARNA]},
4:{context:'Gen 4 sposta la frattura dalla coppia originaria alla fraternità e alla società. Pastorizia, agricoltura, città, metallurgia e musica sono presentate come aspetti della crescita culturale, mentre la violenza cresce da Caino a Lamec. Le tradizioni sulle origini di mestieri e gruppi hanno carattere eziologico: non costituiscono una cronologia archeologica delle invenzioni, ma organizzano memoria culturale e identità.',formation:'Il capitolo combina il racconto Caino-Abele, la discendenza di Caino e la ripresa della linea di Set. Le somiglianze onomastiche con Gen 5 suggeriscono tradizioni genealogiche parallele o correlate. La ricerca discute la storia precisa delle aggiunte, ma è chiaro che la redazione finale ha conservato due modi diversi di raccontare le prime generazioni, integrandoli nella progressione da creazione a diluvio.',textual:'Il v. 8 presenta una nota difficoltà: nel MT Caino “disse” ad Abele senza che siano conservate le parole; LXX, Samaritano e altre versioni aggiungono l’invito “andiamo in campagna”, probabilmente riflettendo una forma testuale più esplicita. È un caso didatticamente importante in cui le versioni antiche possono preservare materiale assente nel MT. Anche il segno di Caino resta volutamente non specificato.',bibliography:[W1,WEST1,CARR,CARRF]},
5:{context:'La genealogia di Gen 5 costruisce un tempo primordiale attraverso longevità eccezionali e successione ordinata delle generazioni. Liste regali e genealogiche mesopotamiche mostrano che l’antico Vicino Oriente poteva rappresentare il passato remoto mediante età schematiche e straordinarie. Il testo non va quindi trattato automaticamente come registro anagrafico moderno; la formula “e morì” rende teologicamente visibile la mortalità.',formation:'Gen 5 appartiene chiaramente al sistema sacerdotale delle toledot e collega Adamo a Noè. La genealogia presenta corrispondenze con i nomi di Gen 4 ma una diversa organizzazione. La sua funzione compositiva è decisiva: trasforma le origini in una sequenza generazionale e prepara il diluvio, mentre Enoch interrompe intenzionalmente la formula della morte.',textual:'MT, LXX e Pentateuco Samaritano presentano età differenti per diversi patriarchi, producendo cronologie complessive diverse dalla creazione al diluvio. Non si tratta di semplici errori isolati: i numeri mostrano interventi sistematici nelle tradizioni testuali. Per questo una data assoluta della creazione ricavata sommando le età dipende dal testimone scelto e non rappresenta un dato univoco del testo biblico.',bibliography:[W1,WEST1,CARR,SARNA]},
6:{context:'Gen 6,1–4 conserva un frammento mitico sui “figli di Dio”, le donne e i nefilim, inserito in una cornice che conduce al diluvio. Il resto del capitolo interpreta la catastrofe come risposta alla violenza e corruzione umana. Tradizioni mesopotamiche di diluvio, in particolare Atrahasis e Gilgamesh, costituiscono comparanda essenziali, ma la motivazione etica e la sovranità del Dio unico distinguono profondamente la narrazione biblica.',formation:'Il capitolo rende visibile l’intreccio di materiali non-P e P. 6,5–8 usa linguaggio antropopatico e introduce Noè; 6,9–22 presenta genealogia, corruzione della terra, misure dell’arca e alleanza con caratteristiche sacerdotali. La ricerca non concorda su ogni versetto, ma la compresenza di due fili narrativi nel ciclo del diluvio è uno dei casi classici della critica compositiva della Genesi.',textual:'Il testo di 6,1–4 contiene termini e referenti oscuri, soprattutto bene ha-elohim e nefilim; le versioni antiche testimoniano interpretazioni diverse più che una soluzione testuale certa. In 6,3 anche il valore di yadon è discusso. Le difficoltà invitano a distinguere ciò che può essere stabilito criticamente dal testo da ciò che resta interpretazione del suo immaginario arcaico.',bibliography:[W1,WEST1,CARR,CARRF]},
7:{context:'La descrizione del diluvio combina immagini di pioggia, abisso e “finestre del cielo”, coerenti con la cosmologia antica delle acque sopra e sotto il mondo abitato. Il racconto non nasce come relazione geologica moderna. Il suo confronto con tradizioni mesopotamiche mostra un patrimonio narrativo regionale condiviso, rielaborato attorno a violenza umana, giustizia di Noè e preservazione della vita.',formation:'Gen 7 conserva segnali particolarmente evidenti di composizione: sette paia di animali puri in 7,2–3 e una coppia per specie nel quadro sacerdotale; quaranta giorni di pioggia e una cronologia in mesi e giorni; uso alternato dei nomi divini. La redazione finale non cancella questi doppioni, ma li coordina in una narrazione continua.',textual:'Le principali questioni del capitolo sono compositive più che dovute a grandi divergenze manoscritte. MT, LXX e Samaritano presentano varianti numeriche e formulazioni locali, ma condividono la struttura dell’inondazione. La critica testuale non deve essere usata per eliminare automaticamente le duplicazioni: molte appartengono alla storia letteraria precedente alla trasmissione manoscritta.',bibliography:[W1,WEST1,CARR,BADEN]},
8:{context:'Il ritiro delle acque, l’invio degli uccelli e il sacrificio di Noè hanno paralleli significativi nell’epica di Gilgamesh. Il confronto mostra sia memoria narrativa comune sia trasformazione teologica: nel testo biblico il sacrificio non placa dèi affamati, e la promessa di stabilità nasce da una decisione divina sul rapporto con una umanità ancora incline al male.',formation:'La sequenza alterna ancora materiali P e non-P. Date precise, abbassamento delle acque e ordine di uscita appartengono al quadro sacerdotale; corvo/colomba, altare e promessa di 8,20–22 sono normalmente collegati al filo non-P. La formula “Dio si ricordò di Noè” in 8,1 funge da perno narrativo dell’intero ciclo.',textual:'Le versioni mostrano differenze minori nella sequenza e formulazione dell’invio degli uccelli, ma non un’altra trama. Il rapporto con Gilgamesh è una questione di storia delle tradizioni, non di critica testuale: somiglianze con testi mesopotamici non sono “varianti” della Bibbia. MT rimane la base, da confrontare puntualmente con LXX e Samaritano.',bibliography:[W1,WEST1,CARR,SARNA]},
9:{context:'L’alleanza con Noè universalizza la responsabilità per la vita: riguarda l’umanità e “ogni essere vivente”. Le norme sul sangue riflettono la concezione biblica della vita come appartenente a Dio. La scena finale su Noè, Cam e Canaan è invece una tradizione familiare ed eziologica legata ai rapporti fra gruppi; non fornisce alcun fondamento testuale alle moderne ideologie razziste.',formation:'9,1–17 continua il quadro sacerdotale del diluvio con benedizione, norme alimentari, alleanza e segno dell’arco. 9,18–27 appartiene a un diverso complesso narrativo, collegato alla storia delle origini mediante Noè e i figli. L’accostamento mostra come la forma finale unisca universalismo dell’alleanza e memorie particolari sulle relazioni fra popoli.',textual:'La tradizione testuale dell’alleanza è stabile. In 9,25 il testo maledice esplicitamente Canaan, non Cam: questo dato è decisivo contro interpretazioni posteriori che hanno trasferito la maledizione a popolazioni africane. Le versioni antiche confermano sostanzialmente il referente. Le difficoltà riguardano piuttosto la logica narrativa che avrebbe portato dalla colpa di Cam alla maledizione del figlio.',bibliography:[W1,WEST1,CARR,SARNA]},
10:{context:'La “tavola delle nazioni” organizza il mondo conosciuto dagli autori in genealogie che sono anche geografia politica. Molti nomi corrispondono a popoli e territori del primo millennio a.C.; non sono categorie biologiche o razziali. L’orizzonte si estende dall’Egeo e Anatolia alla Mesopotamia, Egitto e Levante, presentando l’umanità postdiluviana come rete di parentela.',formation:'Il capitolo combina materiale sacerdotale, riconoscibile nelle formule genealogiche e nelle conclusioni per famiglie/lingue/terre, con espansioni narrative come Nimrod. La sua collocazione fra Noè e Babele crea una tensione intenzionale: Gen 10 conosce già popoli e lingue differenti, mentre Gen 11 narra eziologicamente la dispersione linguistica.',textual:'Le versioni antiche presentano varianti soprattutto nei nomi propri e nelle liste, terreno naturalmente esposto a errori di copia e adattamenti fonetici. La LXX può conservare forme differenti di etnonimi. L’identificazione moderna dei nomi richiede quindi confronto filologico, epigrafico e geografico; non ogni somiglianza fonetica costituisce identificazione storica.',bibliography:[W1,WEST1,CARR,CARRF]},
11:{context:'Babele riflette il mondo urbano mesopotamico, con costruzione in mattoni e bitume e una torre che richiama l’ambiente delle ziqqurat. Il racconto non descrive ingenuamente l’origine scientifica delle lingue: usa Babilonia come simbolo di concentrazione, fama e progetto umano totalizzante. La genealogia successiva sposta poi l’orizzonte universale verso la famiglia di Terach.',formation:'11,1–9 è normalmente letto nel complesso non-P della storia delle origini; 11,10–26 riprende il sistema genealogico sacerdotale di Gen 5. 11,27–32 introduce le toledot di Terach e prepara Abramo. La giunzione fra questi materiali è strutturalmente decisiva: dalla dispersione dei popoli emerge la famiglia attraverso cui la benedizione sarà nuovamente indirizzata alle nazioni.',textual:'Le differenze più importanti riguardano ancora la cronologia genealogica: MT, LXX e Samaritano attribuiscono età diverse ai patriarchi postdiluviani. In 11,1–9 le varianti sono meno sostanziali. L’etimologia narrativa di Babele da balal (“confondere”) è un gioco di parole ebraico; storicamente il nome Babilonia deriva dall’accadico Bab-ilim/Babili.',bibliography:[W1,WEST1,CARR,SCHMID]},
12:{context:'Gli itinerari di Abram attraversano Alta Mesopotamia, Canaan ed Egitto, ma non permettono di datare il patriarca con precisione nel II millennio a.C. La mobilità pastorale e i rapporti fra Levante ed Egitto sono storicamente plausibili in molte epoche. Il valore storico del capitolo consiste quindi nel suo radicamento in geografie reali e memorie sociali, non nell’identificazione di Abram con un individuo extrabiblico documentato.',formation:'12,1–3 costituisce un programma teologico che lega terra, discendenza e benedizione delle famiglie della terra. Itinerari, altari e promesse sono stati integrati in una sequenza che apre il ciclo di Abramo. L’episodio della moglie-sorella in Egitto ha paralleli in Gen 20 e 26: la loro relazione può essere spiegata con tradizioni parallele, riscritture o fonti differenti, senza consenso unico.',textual:'Il testo è relativamente stabile. In 12,3 la forma verbale relativa alla benedizione delle famiglie può essere resa riflessivamente (“si diranno benedette”) o passivamente (“saranno benedette”), questione importante nella ricezione successiva. Le versioni antiche aiutano a documentare la storia interpretativa ma non eliminano l’ambiguità dell’ebraico.',bibliography:[W1,WEST2,SARNA,H1]},
13:{context:'La separazione di Abram e Lot presuppone un’economia pastorale nella quale greggi, acqua e pascoli possono generare conflitto fra gruppi imparentati. Betel, Ai, valle del Giordano e Mamre sono luoghi reali della geografia levantina, ma la narrazione li organizza teologicamente attorno alla promessa della terra. La descrizione della pianura “come l’Egitto” riflette memoria geografica, non una datazione automatica.',formation:'Il capitolo prosegue e rielabora temi di Gen 12: ritorno all’altare, promessa, itinerario e scelta della terra. La separazione di Lot prepara Gen 18–19 e definisce progressivamente la linea ancestrale. Le formule di promessa in 13,14–17 possono riflettere ampliamenti redazionali che rafforzano il possesso futuro della terra nel quadro complessivo del Pentateuco.',textual:'Le varianti sono perlopiù locali, specialmente in toponimi e formulazioni della promessa. L’espressione temporale di 13,7 (“il Cananeo e il Perizzita abitavano allora nel paese”) è importante per la prospettiva narrativa, ma non consente da sola di datare il testo. MT e LXX conservano sostanzialmente la stessa progressione.',bibliography:[W1,WEST2,BLUM,SARNA]},
14:{context:'Gen 14 presenta una geografia internazionale di re e città che ha generato numerosi tentativi di identificazione storica. Nessuna proposta permette però di ricostruire con sicurezza la coalizione o di datare Abramo attraverso questi nomi. Melchisedek, re-sacerdote di Salem, riflette un modello di regalità sacerdotale del Levante e diventerà figura importante nella ricezione biblica successiva.',formation:'Il capitolo è stilisticamente isolato nel ciclo di Abramo: usa titoli, liste regali e una campagna militare assenti altrove. Molti studiosi lo considerano una tradizione autonoma inserita nel ciclo; la scena di Melchisedek e il rapporto con il re di Sodoma possono avere una propria storia redazionale. La forma finale presenta Abram come attore regionale ma indipendente dai beni di Sodoma.',textual:'I nomi propri di Gen 14 pongono difficoltà filologiche e hanno varianti nelle versioni. La LXX spesso traslittera o interpreta. Il v. 20 e la decima ad Abram/Melchisedek hanno una sintassi che la tradizione ha letto in modo relativamente stabile, ma la direzione del dono va ricavata dal contesto. La critica testuale non conferma identificazioni speculative dei re.',bibliography:[W1,WEST2,H1,SARNA]},
15:{context:'Il capitolo utilizza forme di promessa, visione e alleanza. Il rito degli animali divisi trova analogie in pratiche di alleanza del Vicino Oriente antico, dove il passaggio fra parti poteva simbolizzare una sanzione. La menzione di confini e popoli guarda alla terra da una prospettiva teologica e politica successiva rispetto al tempo narrato.',formation:'Gen 15 è compositivamente complesso: promessa di discendenza (vv. 1–6) e promessa della terra con rito (vv. 7–21) mostrano lessico e dinamiche differenti. Le vecchie attribuzioni J/E non esauriscono il dibattito; molti modelli vedono crescita e integrazione di tradizioni della promessa. 15,6 è diventato nodo canonico importante, ma nel contesto lega la fiducia di Abram alla parola divina.',textual:'In 15,2–3 il testo ebraico contiene espressioni difficili relative all’erede/servo di Damasco; versioni antiche mostrano tentativi interpretativi. La lista dei popoli in 15,19–21 varia in tradizioni e paralleli biblici. Il nucleo della promessa e del rito è tuttavia ben attestato. Le difficoltà non autorizzano una ricostruzione storica precisa dei confini descritti.',bibliography:[W1,WEST2,H1,BLUM]},
16:{context:'La vicenda di Agar riflette istituzioni domestiche del Vicino Oriente antico nelle quali una schiava poteva essere coinvolta nella produzione di discendenza per una padrona sterile. Paralleli giuridici mesopotamici aiutano a comprendere il quadro sociale, ma non dimostrano una data patriarcale specifica: pratiche simili sono attestate in periodi diversi. Il racconto dà inoltre voce e incontro divino a una donna schiava e straniera.',formation:'Gen 16 appartiene al complesso non-P del ciclo di Abramo, ma è stato coordinato con la genealogia sacerdotale di Gen 17. La promessa su Ismaele crea una linea benedetta ma distinta da quella di Isacco. Il racconto contiene eziologie del nome Ismaele e del pozzo Beer-Lacai-Roi, segnali della formazione tradizionale attorno a luoghi e gruppi.',textual:'Il testo è generalmente stabile. In 16,12 la descrizione di Ismaele come pere adam è semanticamente forte e va resa senza sovraccaricarla con stereotipi posteriori. I toponimi e il nome del pozzo hanno varianti ortografiche nelle versioni. La LXX interpreta alcuni passaggi ma non testimonia una trama alternativa.',bibliography:[W2,WEST2,H1,SARNA]},
17:{context:'Circoncisione, cambio di nome e promessa dinastica sono inseriti in un quadro di identità familiare e alleanza. La circoncisione era conosciuta in varie culture antiche, incluso l’Egitto, ma Gen 17 le attribuisce una funzione specifica: segno dell’alleanza per i maschi della casa di Abramo, inclusi schiavi e stranieri incorporati. Il capitolo definisce anche il rapporto fra Isacco e Ismaele senza negare la benedizione di quest’ultimo.',formation:'Il capitolo è uno dei testi sacerdotali più riconoscibili della Genesi: El Shaddai, alleanza eterna, genealogia, età precise, cambio dei nomi e segno corporeo formano un sistema coerente. Esso rilegge e struttura le promesse abramitiche in forma istituzionale. La sua relazione con Gen 15 mostra due configurazioni letterarie dell’alleanza conservate entrambe nella forma finale.',textual:'MT, LXX e Samaritano concordano sostanzialmente. Le principali differenze riguardano dettagli numerici e formulazioni. Il gioco fra Abram/Abraham e Sarai/Sarah è spiegato narrativamente più che etimologicamente in senso scientifico. In 17,14 la sanzione del “taglio” della persona non circoncisa usa la radice krt, la stessa associata all’espressione “concludere/tagliare” un’alleanza.',bibliography:[W2,WEST2,H1,BADEN]},
18:{context:'L’ospitalità presso Mamre appartiene a un mondo nel quale accogliere viandanti era un dovere sociale essenziale. La scena dei tre visitatori gioca deliberatamente fra apparizione divina e pluralità dei personaggi. La trattativa su Sodoma assume forma quasi giudiziaria e mette al centro la giustizia del giudice di tutta la terra, più che offrire informazioni storiche sulla città.',formation:'Gen 18 unisce annuncio della nascita e intercessione per Sodoma, collegando ciclo di Abramo e storia di Lot. La narrazione è normalmente collocata nel materiale non-P; possibili ampliamenti teologici sono discussi, soprattutto nel dialogo dei vv. 17–19 sulla vocazione di Abramo a trasmettere giustizia e diritto. La forma finale prepara simultaneamente Gen 19 e Gen 21.',textual:'Il testo è ben conservato, ma 18,22 presenta una celebre tradizione scribale: secondo annotazioni masoretiche antiche, la formulazione avrebbe subito una correzione reverenziale riguardo a chi “stava davanti” a chi. È un esempio importante della consapevolezza scribale della trasmissione. Le versioni mostrano inoltre interpretazioni del passaggio fra YHWH e i tre uomini.',bibliography:[W2,WEST2,H2,SARNA]},
19:{context:'Il racconto di Sodoma combina violazione dell’ospitalità, minaccia di violenza sessuale collettiva, giudizio urbano e salvezza di Lot. Ridurlo a una sola questione morale moderna impoverisce il testo: Ezechiele 16,49–50, ad esempio, associa Sodoma anche ad arroganza e mancato soccorso del povero. Le tradizioni sulla moglie di Lot e sulle origini di Moab e Ammon hanno carattere eziologico.',formation:'Gen 19 continua direttamente Gen 18 con i due messaggeri e chiude la storia di Lot iniziata in Gen 13. La seconda parte, con le figlie di Lot, spiega narrativamente rapporti problematici fra Israele e popoli transgiordanici. L’insieme appartiene prevalentemente al filo non-P, ma la forma finale è stata integrata nel più ampio sistema delle promesse e delle separazioni genealogiche.',textual:'La tradizione testuale è relativamente stabile, pur con varianti minori nella descrizione della distruzione e dei personaggi. Il verbo “conoscere” in 19,5, nel contesto della minaccia collettiva, ha valore sessuale chiarito dalla risposta di Lot. Il termine tradotto “zolfo” designa materiale combustibile, ma non consente di identificare con certezza un singolo evento archeologico.',bibliography:[W2,WEST2,H2,SARNA]},
20:{context:'La seconda storia della moglie-sorella trasferisce l’episodio a Gerar e introduce Abimelech. Il racconto riflette rapporti fra gruppi, protezione dello straniero e vulnerabilità delle donne in sistemi patriarcali. L’etichetta “Filistei” associata altrove a Gerar appartiene a una geografia narrativa che può riflettere realtà più tarde del primo millennio, e non prova una data del patriarca.',formation:'Il parallelo con Gen 12,10–20 è evidente ma le differenze sono sostanziali: qui Abramo spiega la parentela, Dio parla ad Abimelech in sogno e Abramo è chiamato profeta. Nella teoria documentaria classica il capitolo era spesso attribuito a E; oggi la relazione fra i racconti è discussa in termini di tradizioni parallele e riscrittura. Gen 26 offrirà una terza variazione.',textual:'Il testo presenta alcune difficoltà sintattiche, soprattutto nella spiegazione di Abramo in 20,12–13. Le versioni cercano di rendere il rapporto di parentela senza eliminarne l’ambiguità. In 20,16 il riferimento a “mille sicli” e alla copertura degli occhi è interpretativamente difficile; non esiste una variante che risolva definitivamente la metafora.',bibliography:[W2,WEST2,H2,BLUM]},
21:{context:'La nascita di Isacco realizza la promessa e conduce alla separazione di Agar e Ismaele. Il deserto di Bersabea e Paran colloca la narrazione nel margine meridionale di Canaan. La scena del pozzo riflette la centralità dell’acqua per gruppi pastorali. Il racconto conserva una forte tensione etica: l’elezione di Isacco non equivale all’abbandono di Ismaele, che riceve protezione e promessa di una grande nazione.',formation:'Il capitolo intreccia formule sacerdotali sulla nascita e circoncisione di Isacco con la narrazione non-P dell’allontanamento di Agar. La relazione con Gen 16 mostra due racconti di pericolo e promessa per Agar/Ismaele. L’episodio di Abimelech e Bersabea prepara inoltre Gen 26, dove temi simili saranno trasferiti a Isacco.',textual:'In 21,9 il participio metsaheq, collegato alla radice del nome Isacco, può significare “giocare/ridere” e ha ricevuto interpretazioni più negative nella tradizione; il MT non specifica esplicitamente l’azione ostile. La LXX rende il termine in modo che ha influenzato la ricezione paolina. È un caso in cui traduzione e interpretazione incidono fortemente sulla lettura.',bibliography:[W2,WEST2,H2,SARNA]},
22:{context:'Il sacrificio di figli è attestato e polemizzato in diversi testi del Levante antico; Gen 22 va letto in questo orizzonte senza assumere che descriva una normale pratica israelita. Il racconto conduce fino al gesto estremo ma lo interrompe e sostituisce Isacco con un ariete. Nella tradizione ebraica diventerà l’Aqedah, “legatura”, mentre la lettura cristiana svilupperà ulteriori connessioni tipologiche.',formation:'La narrazione è costruita con grande economia e ripetizioni (“eccomi”, “insieme”, “tuo figlio, il tuo unico”). La designazione del luogo come Moria in 22,2 e il collegamento con il monte di YHWH in 22,14 favoriscono una rilettura in rapporto a Gerusalemme/Tempio. I vv. 15–18, seconda parola angelica con giuramento e promessa, sono spesso considerati un ampliamento redazionale.',textual:'In 22,14 il MT conserva un gioco toponimico/teologico difficile, “YHWH vede/provvede”; le versioni rendono secondo diverse sfumature. Il termine “unico” (yahid) riferito a Isacco esprime unicità affettiva e della promessa, pur esistendo Ismaele. Le principali questioni sono esegetiche e redazionali, non una divergenza radicale fra testimoni.',bibliography:[W2,WEST2,H2,BLUM]},
23:{context:'L’acquisto della grotta di Macpela presenta una transazione fondiaria formalizzata davanti alla comunità. Confronti con documenti giuridici del Vicino Oriente aiutano a comprendere negoziazione, prezzo e testimonianza pubblica, ma non consentono di datare il racconto attraverso una singola formula legale. Letterariamente, il primo possesso stabile di Abramo nella terra promessa è un sepolcro.',formation:'Il capitolo forma un’unità compatta e svolge una funzione strutturale nel ciclo di Abramo: dopo la promessa della terra, Abramo acquisisce legalmente un piccolo terreno. Lessico, ripetizioni e precisione giuridica sono stati variamente collegati a tradizioni sacerdotali o a una prosa tarda, ma l’attribuzione puntuale resta discussa. Gen 25 e 49–50 riprenderanno Macpela come tomba ancestrale.',textual:'Il testo è sostanzialmente stabile. Il nome del proprietario Efron e l’espressione “figli di Het” hanno varianti minori nelle versioni, ma la transazione resta chiara. Il prezzo di quattrocento sicli è narrativamente elevato; non è possibile convertirlo con precisione in valore moderno né usarlo come indicatore cronologico sicuro.',bibliography:[W2,WEST2,H2,SARNA]},
24:{context:'La ricerca di una moglie per Isacco riflette strategie matrimoniali endogamiche, reti di parentela e trasferimenti fra Canaan e Alta Mesopotamia. Il viaggio del servo, l’incontro al pozzo e i doni nuziali appartengono a convenzioni sociali e narrative ampiamente comprensibili nel Vicino Oriente. Rebecca, tuttavia, non è figura passiva: decide di partire e diventa agente della continuità della promessa.',formation:'Gen 24 è una lunga novella unitaria costruita mediante ripetizione: il servo racconta quasi integralmente ciò che il narratore ha appena narrato, ma con adattamenti retorici. Questa tecnica caratterizza l’arte narrativa del capitolo. La storia collega la morte di Sara alla successione generazionale e mantiene la famiglia di Abramo distinta dall’ambiente cananeo senza abbandonare la terra.',textual:'Le varianti sono generalmente minori. In 24,2 e 24,9 il gesto della mano sotto la coscia è un rito di giuramento dal significato preciso non pienamente ricostruibile; le versioni lo conservano senza spiegarlo. Alcuni nomi e dettagli dei doni differiscono nella tradizione, ma la lunga ripetizione interna offre anche un controllo letterario sulla stabilità del racconto.',bibliography:[W2,WEST2,H2,SARNA]},
25:{context:'Il capitolo chiude la vita di Abramo e apre il conflitto fra Esaù e Giacobbe. Le genealogie di Keturah e Ismaele collocano Israele in una rete di parentele con gruppi arabi e transgiordanici. Il racconto della primogenitura riflette il valore sociale del diritto del primogenito, ma lo usa narrativamente per spiegare la futura preminenza di Giacobbe/Israele.',formation:'25,1–18 raccoglie tradizioni genealogiche che completano le linee collaterali prima di concentrare la narrazione su Isacco. 25,19 introduce una nuova toledot; la nascita dei gemelli e la vendita della primogenitura avviano il ciclo di Giacobbe. La forma finale usa genealogie come dispositivi di separazione e inclusione: i popoli parenti sono benedetti ma la promessa segue una linea specifica.',textual:'In 25,18 la descrizione dell’insediamento ismaelita presenta difficoltà di resa; in 25,23 l’oracolo sui “due popoli” lega i gemelli a realtà collettive. Il gioco Edom/adom (“rosso”) e il soprannome legato alla minestra sono etimologie narrative. MT e versioni concordano nel nucleo, con differenze soprattutto lessicali.',bibliography:[W2,WEST2,H2,BLUM]},
26:{context:'Il ciclo di Isacco è relativamente breve e Gen 26 ne costituisce il centro autonomo. Carestia, pozzi, dispute pastorali e trattato con Abimelech riflettono la competizione per acqua e territorio nel Negev settentrionale. Il riferimento ai Filistei appartiene probabilmente alla geografia conosciuta dai tradenti più tardi e non dimostra che il racconto risalga all’epoca tradizionalmente attribuita a Isacco.',formation:'Il capitolo riprende motivi abramitici: carestia, Gerar, moglie-sorella, Abimelech, pozzi, giuramento e Bersabea. La ripetizione può riflettere tradizioni parallele applicate a diversi patriarchi o una deliberata costruzione letteraria della continuità fra Abramo e Isacco. I vv. 34–35 sulle mogli ittite di Esaù preparano direttamente Gen 27–28.',textual:'Le varianti riguardano soprattutto nomi di pozzi e dettagli locali. In 26,8 il verbo relativo a Isacco e Rebecca gioca sulla radice ts-h-q, la stessa di “Isacco”, con senso di comportamento intimo/giocoso. Le versioni rendono interpretativamente. Non esiste base testuale per trasformare i racconti paralleli di Gen 12, 20 e 26 in un unico episodio storico.',bibliography:[W2,WEST2,H2,BLUM]},
27:{context:'La benedizione paterna è presentata come parola efficace legata a successione familiare, terra e prosperità. Il travestimento di Giacobbe e l’azione di Rebecca mettono in scena conflitti di preferenza e strategie domestiche. Il capitolo non offre un modello morale semplice: la promessa procede attraverso personaggi ambigui, mentre Esaù appare vittima reale dell’inganno.',formation:'Gen 27 sviluppa la rivalità annunciata in 25,23 e prepara l’esilio di Giacobbe. La narrazione è spesso considerata non-P; 27,46 funziona da raccordo con il motivo sacerdotale dei matrimoni endogamici in Gen 28. Le due motivazioni della partenza di Giacobbe — fuga da Esaù e ricerca di moglie — mostrano l’integrazione di prospettive compositive differenti.',textual:'Il testo presenta numerosi dialoghi ma è ben attestato. Le benedizioni di 27,27–29 e 27,39–40 contengono poesia e ambiguità: la preposizione in 27,39 può essere resa “dalla fertilità” in senso positivo o “lontano dalla fertilità”. Le versioni testimoniano interpretazioni diverse, con conseguenze sulla caratterizzazione del destino di Esaù.',bibliography:[W2,WEST2,H2,BLUM]},
28:{context:'Betel era un importante santuario del regno del Nord. Il racconto della scala/rampa e della “casa di Dio” conserva memoria cultuale collegata al luogo, successivamente integrata nella storia di Giacobbe. L’immagine di una struttura che unisce terra e cielo trova analogie nell’architettura sacra mesopotamica, ma nel racconto è YHWH a stare presso/sopra Giacobbe e a confermare la promessa.',formation:'Il capitolo combina la partenza motivata dal matrimonio, di profilo sacerdotale, con il sogno di Betel, generalmente non-P. La promessa riprende temi abramitici e li trasferisce a Giacobbe. La stele, l’olio e il voto possono conservare una tradizione eziologica sul santuario di Betel, reinterpretata nella forma pentateucale.',textual:'In 28,12 il tradizionale “scala” traduce sullam, termine unico nella Bibbia e forse meglio inteso come rampa/scalinata. In 28,13 la posizione di YHWH può essere resa “sopra di essa” o “accanto a lui”, ambiguità grammaticale reale. Le versioni antiche hanno influenzato fortemente l’immaginario successivo della scala di Giacobbe.',bibliography:[W2,WEST2,H2,BLUM]},
29:{context:'L’incontro al pozzo, il matrimonio e il servizio presso la famiglia materna riflettono convenzioni di parentela e negoziazione matrimoniale. Il racconto mostra però anche vulnerabilità e competizione fra Lia e Rachele in un sistema nel quale fertilità e posizione della moglie incidono sulla sicurezza sociale. I nomi dei figli vengono interpretati attraverso giochi di parole teologici ed emotivi.',formation:'Gen 29–30 forma un complesso narrativo sulla costruzione della famiglia di Giacobbe. La sostituzione di Rachele con Lia rovescia ironicamente l’inganno del primogenito di Gen 27. Tradizioni sui figli e sulle madri delle tribù sono state integrate in una storia familiare continua; le etimologie dei nomi mostrano più voci e motivazioni, non un unico schema uniforme.',textual:'I giochi di parole sui nomi — Ruben, Simeone, Levi, Giuda — dipendono dall’ebraico e spesso non possono essere riprodotti pienamente in traduzione. Le versioni mantengono il senso generale ma perdono o reinterpretano le assonanze. Alcuni dettagli temporali del servizio a Labano variano nella resa, senza modificare l’impianto.',bibliography:[W2,WEST2,H2,BLUM]},
30:{context:'La competizione per i figli coinvolge Rachele, Lia e le serve Bila e Zilpa, riflettendo una casa patriarcale complessa. Le mandragore erano associate alla fertilità nel mondo antico. La seconda metà, sul bestiame maculato e striato, usa concezioni premoderne della riproduzione animale: il racconto non è un trattato genetico, ma una narrazione di astuzia, prosperità e conflitto economico.',formation:'Il capitolo continua il dossier delle nascite e conduce alla crescita economica di Giacobbe. Le differenti spiegazioni dei nomi tribali e le transizioni fra scene hanno favorito analisi di fonti, ma la ricostruzione J/E versetto per versetto resta controversa. La forma finale presenta la moltiplicazione della famiglia e dei beni come preparazione al ritorno in Canaan.',textual:'I nomi dei figli contengono numerosi giochi fonetici difficili da trasferire nelle versioni. In 30,32–43 la terminologia dei colori e delle caratteristiche del bestiame è tecnica e talvolta incerta; LXX e altre versioni non sempre coincidono nelle equivalenze. Le differenze consigliano cautela nelle ricostruzioni zoologiche troppo precise.',bibliography:[W2,WEST2,H2,BLUM]},
31:{context:'La fuga da Labano attraversa lo spazio fra Alta Mesopotamia e Galaad. I terafim sottratti da Rachele sono oggetti cultuali domestici attestati nel Vicino Oriente, ma la loro funzione esatta nel racconto — religiosa, ereditaria o simbolica — resta discussa. Il patto di confine con stele e mucchio di pietre riflette la sacralizzazione di limiti territoriali e obblighi reciproci.',formation:'Gen 31 chiude il lungo soggiorno presso Labano e prepara l’incontro con Esaù. Il capitolo presenta ripetizioni e versioni diverse della motivazione della partenza, del successo economico e dell’intervento divino, tradizionalmente distribuite fra fonti. La forma finale le usa per mostrare Giacobbe progressivamente liberato dal controllo di Labano.',textual:'La terminologia dei terafim è stabile, ma la loro interpretazione dipende da confronti extrabiblici. In 31,47 il mucchio riceve un nome aramaico da Labano e uno ebraico da Giacobbe: la doppia denominazione è un raro segnale linguistico intenzionale. Le versioni conservano la distinzione, importante per la caratterizzazione etnica dei personaggi.',bibliography:[W2,WEST2,H2,BLUM]},
32:{context:'Il ritorno di Giacobbe culmina nella notte allo Iabbok, confine naturale della Transgiordania. Il combattimento con l’essere misterioso appartiene al linguaggio delle tradizioni di teofania e dei racconti eziologici: spiega il nome Israele e una pratica alimentare. Il testo resiste a identificare semplicemente l’avversario; la sua ambiguità è parte della forza narrativa.',formation:'Il capitolo lega preparazione diplomatica all’incontro con Esaù, preghiera, divisione dei doni e lotta notturna. La scena dello Iabbok può aver avuto origine come tradizione autonoma su Peniel e sul nome Israele, poi incorporata nella biografia di Giacobbe. La trasformazione del nome non cancella immediatamente “Giacobbe”: entrambi continueranno a essere usati.',textual:'La numerazione dei versetti differisce fra tradizioni moderne (il capitolo può iniziare con materiale numerato 31,55 altrove). In 32,29 il nome Israel è spiegato mediante il verbo sarah, etimologia narrativa non necessariamente linguistica storica. Il termine per il nervo/tendine in 32,33 è raro e la sua identificazione anatomica resta discussa.',bibliography:[W2,WEST2,H2,BLUM]},
33:{context:'L’incontro fra Giacobbe ed Esaù mette in scena pratiche di deferenza, doni e riconciliazione fra capi di gruppi familiari. La geografia conduce da Peniel/Succot verso Sichem, mentre Esaù torna a Seir. Il racconto non riduce Edom a nemico: Esaù corre incontro al fratello e lo abbraccia, elemento importante rispetto alle polemiche anti-edomite di altri testi biblici.',formation:'Gen 33 risolve il conflitto aperto in Gen 27 senza cancellare la separazione fra i due fratelli. La narrazione dei doni è preparata nel capitolo precedente. Il finale con altare presso Sichem collega Giacobbe alle tradizioni cultuali già associate ad Abramo e prepara il drammatico episodio di Gen 34.',textual:'In 33,4 il verbo relativo al bacio di Esaù porta nella tradizione masoretica puncta extraordinaria, punti sopra le lettere che segnalano una particolare attenzione scribale. La tradizione rabbinica ne ha discusso il significato, ma il testo consonantico dice che Esaù baciò Giacobbe. È un eccellente esempio di paratesto masoretico da distinguere da una variante manoscritta ordinaria.',bibliography:[W2,WEST2,H2,SARNA]},
34:{context:'La vicenda di Dina e Sichem riflette questioni di violenza sessuale, matrimonio intergruppo, onore familiare e vendetta. Il racconto non deve essere trasformato in semplice giustificazione della strage: Giacobbe condanna le conseguenze dell’azione di Simeone e Levi, e Gen 49,5–7 giudicherà duramente la loro violenza. La città di Sichem è un importante centro storico del Levante centrale.',formation:'Il capitolo combina la vicenda di Dina con negoziazioni collettive fra la famiglia di Giacobbe e gli uomini della città. Alcune tensioni — chi propone il matrimonio, chi negozia, chi compie la vendetta — hanno suggerito più strati o tradizioni. La forma finale collega il tema dell’identità matrimoniale alla circoncisione in modo volutamente problematico e prepara la partenza da Sichem.',textual:'Il verbo usato per l’azione contro Dina e la sequenza “vide, prese, giacque, umiliò” sono semanticamente decisivi; traduzioni attenuanti possono alterare la percezione della violenza. In 34,3 il linguaggio dell’attaccamento e dell’amore non annulla quanto narrato prima. Le varianti testuali sono secondarie rispetto alla necessità di leggere con precisione il lessico ebraico.',bibliography:[W2,WEST2,H2,BLUM]},
35:{context:'Betel riappare come luogo di culto e memoria ancestrale. L’ordine di eliminare dèi stranieri e purificarsi riflette una prospettiva di esclusività cultuale sviluppata nella tradizione israelita. Le morti di Debora e Rachele e la nascita di Beniamino ancorano il racconto a luoghi e sepolture, mentre la lista dei figli ricapitola la famiglia prima del passaggio a Esaù e Giuseppe.',formation:'Il capitolo intreccia ritorno a Betel, nuova conferma del nome Israele, genealogia e notizie di morte. La ripetizione del cambio di nome rispetto a Gen 32 è un chiaro segnale di tradizioni parallele: 35,9–15 ha forte profilo sacerdotale. La forma finale conserva entrambe le scene, una narrativa allo Iabbok e una teofanica a Betel.',textual:'In 35,19–20 la localizzazione della tomba di Rachele “sulla via di Efrata, cioè Betlemme” entra in dialogo con altre tradizioni bibliche che la collocano nel territorio beniaminita. Non è principalmente un problema di variante testuale ma di memoria geografica plurale. I nomi Ben-Oni/Beniamino sono spiegati narrativamente con un cambio intenzionale.',bibliography:[W2,WEST2,H2,BLUM]},
36:{context:'La genealogia di Esaù/Edom presenta Edom come popolo fratello con propri clan, capi e re. La lista dei re “prima che regnasse un re sugli Israeliti” riflette una prospettiva narrativa che conosce la monarchia israelita e costituisce un importante indizio per la storia della tradizione. I nomi collegano il testo alla geografia di Seir e della Transgiordania meridionale.',formation:'Gen 36 è una grande unità genealogica che chiude la linea di Esaù prima di passare alla toledot di Giacobbe in Gen 37. Il materiale contiene più liste — discendenti, capi, abitanti di Seir, re, capi edomiti — non perfettamente sovrapponibili, probabilmente raccolte da tradizioni differenti. La redazione le conserva per situare Israele dentro una parentela regionale.',textual:'Liste di nomi propri sono particolarmente sensibili a varianti ortografiche; MT, LXX e paralleli in 1 Cronache mostrano differenze. L’identificazione dei singoli capi o luoghi deve quindi evitare eccessiva sicurezza. La frase sui re anteriori alla monarchia israelita è testualmente ben attestata e va affrontata come dato letterario, non rimossa per armonizzazione cronologica.',bibliography:[W2,WEST2,H2,SARNA]},
37:{context:'La storia di Giuseppe si apre nel mondo pastorale di Canaan e conduce verso reti commerciali dirette in Egitto. Carovane di prodotti aromatici dal Transgiordano e traffici fra Levante ed Egitto sono storicamente plausibili in molte epoche. I nomi “Ismaeliti” e “Madianiti” funzionano nel racconto come designazioni di gruppi mercantili, ma la loro alternanza è anche un dato compositivo.',formation:'Gen 37 inaugura una narrazione più continua dei cicli precedenti. Le oscillazioni fra Ruben e Giuda come salvatore, fra Ismaeliti e Madianiti come acquirenti e fra diverse modalità della vendita sono classici indizi di stratificazione. I modelli divergono: combinazione di fonti, crescita successiva o rielaborazione di una novella. È più sicuro presentare le tensioni senza imporre un’unica soluzione.',textual:'In 37,3 ketonet passim è tradizionalmente “tunica dalle lunghe maniche/multicolore”, ma il significato esatto di passim è incerto; la LXX ha contribuito alla tradizione della veste variopinta. Le oscillazioni etnonimiche sono presenti nel testo trasmesso e non vanno corrette automaticamente come errori di copia, perché possono riflettere la composizione.',bibliography:[W2,WEST3,H2,SCHMID]},
38:{context:'La storia di Giuda e Tamar interrompe il racconto di Giuseppe ma affronta temi centrali di discendenza, levirato, vedovanza e giustizia familiare. Il dovere di Onan è affine, pur non identico nella formulazione, al successivo levirato di Dt 25. Tamar agisce entro un sistema che le nega la discendenza promessa; il riconoscimento di Giuda “è più giusta di me” rovescia il giudizio iniziale.',formation:'La collocazione fra Gen 37 e 39 è letterariamente significativa: Giuda, coinvolto nella vendita di Giuseppe, attraversa una trasformazione che prepara il suo ruolo in Gen 43–44. Il capitolo può derivare da una tradizione autonoma su Giuda e i suoi clan, ma la redazione finale lo integra abilmente nella storia di Giuseppe attraverso temi di riconoscimento, oggetti identificativi e responsabilità.',textual:'In 38,5 la località della nascita di Sela presenta varianti e difficoltà. Il lessico relativo alla prostituzione distingue zonah e qedeshah, termini non perfettamente equivalenti; la vecchia resa “prostituta sacra” richiede cautela perché il fenomeno istituzionale è molto discusso. Il testo di 38,26 è stabile nel riconoscimento della maggiore giustizia di Tamar.',bibliography:[W2,WEST3,H2,SARNA]},
39:{context:'La casa di un alto funzionario egiziano, la schiavitù domestica e la prigionia forniscono una cornice egiziana plausibile, ma Potifar non è identificabile con un personaggio storico noto. La scena dell’accusa della moglie appartiene anche a un ampio motivo narrativo internazionale del giovane che rifiuta una seduzione e viene falsamente accusato; i confronti illuminano il genere senza provare dipendenza diretta.',formation:'Gen 39 riprende Giuseppe dopo l’intermezzo di Giuda e Tamar. La formula ripetuta “YHWH era con Giuseppe” struttura ascesa, caduta e nuova ascesa. La storia è narrativamente coesa; le discussioni compositive riguardano soprattutto il suo rapporto con le diverse versioni della vendita in Gen 37 e con la sequenza carceraria dei capitoli successivi.',textual:'Il titolo di Potifar, saris, può significare funzionario e in altri contesti eunuco; qui il ruolo matrimoniale sconsiglia automatismi. Le versioni differiscono in alcuni dettagli dell’accusa, ma non nella trama. La ripetizione della veste lasciata nelle mani della donna crea un motivo letterario di prova/riconoscimento parallelo alla tunica di Gen 37.',bibliography:[W2,WEST3,H2,SARNA]},
40:{context:'Coppiere e panettiere sono uffici di corte ben attestati nel Vicino Oriente e in Egitto; il racconto li usa per collegare Giuseppe al faraone. L’interpretazione dei sogni era pratica riconosciuta nelle culture antiche, con specialisti e manuali, ma Giuseppe attribuisce l’interpretazione a Dio, distinguendo il suo ruolo dalla tecnica divinatoria professionale.',formation:'Il capitolo forma con Gen 41 una sequenza di sogni paralleli: due prigionieri, poi il faraone; ciascuna coppia richiede interpretazione e conduce a un esito. La dimenticanza del coppiere ritarda deliberatamente l’ascesa di Giuseppe. La costruzione è letterariamente controllata e non offre forti ragioni per frammentare il capitolo in molte fonti.',textual:'I termini dei mestieri e alcuni oggetti della corte sono resi diversamente nelle versioni, ma il senso generale è chiaro. La formula “fra tre giorni il faraone solleverà la tua testa” è volutamente ambigua e riceve esiti opposti per coppiere e panettiere. La stabilità della struttura retorica è più significativa delle varianti minori.',bibliography:[W2,WEST3,H2,SARNA]},
41:{context:'Il sogno delle vacche e delle spighe riflette un ambiente nel quale la piena del Nilo e i raccolti determinavano la sicurezza alimentare. L’amministrazione di eccedenze e carestie è storicamente plausibile nell’Egitto faraonico, ma il racconto non permette di identificare la carestia con un episodio documentato preciso. Nomi egiziani e investitura di Giuseppe contribuiscono all’ambientazione letteraria.',formation:'Gen 41 è il grande rovesciamento della storia: il prigioniero straniero diventa amministratore. I due sogni equivalenti, la ripetizione davanti agli esperti e poi a Giuseppe e il piano economico costruiscono una sequenza coerente. Possibili strati restano discussi, ma la forma finale enfatizza sapienza amministrativa e riconoscimento divino da parte del faraone.',textual:'Il nome egiziano Zafenat-Paneach e il nome Asenat sono stati spiegati in vari modi e la loro etimologia resta discussa; non vanno usati come chiavi cronologiche certe. I titoli e termini egizianizzanti hanno varianti di traslitterazione nella LXX. In 41,43 il grido abrek è oscuro e le traduzioni antiche offrono interpretazioni diverse.',bibliography:[W2,WEST3,H2,SARNA]},
42:{context:'La carestia regionale porta i fratelli in Egitto, scenario coerente con il ruolo della valle del Nilo come riserva agricola rispetto a periodiche crisi levantine. Tuttavia il racconto è costruito soprattutto come prova morale e riconoscimento differito: Giuseppe vede i fratelli senza essere riconosciuto, mentre essi reinterpretano il passato alla luce della colpa verso il fratello.',formation:'Gen 42 avvia tre movimenti fra Canaan ed Egitto. Il trattenimento di Simeone, il denaro restituito e la richiesta di Beniamino creano tensione crescente. Ruben riappare come figura che aveva tentato di salvare Giuseppe, in continuità con uno dei fili di Gen 37; la presenza di tradizioni diverse è stata spesso invocata per spiegare il ruolo alternativo di Ruben e Giuda.',textual:'Le varianti sono minori e riguardano soprattutto formulazioni dei dialoghi e quantità. Il termine per “spie” e il linguaggio dell’accusa sono stabili. Il riconoscimento unilaterale di Giuseppe è narrativamente esplicito; non vi sono testimoni che trasformino la scena in un riconoscimento reciproco. La ripetizione del denaro nei sacchi prepara problemi testuali e compositivi nei capitoli successivi.',bibliography:[W2,WEST3,H2,SCHMID]},
43:{context:'Il secondo viaggio mette in primo piano ospitalità, banchetto e gerarchia familiare. La separazione degli Egiziani dagli Ebrei a tavola è spiegata dal narratore come costume egiziano; non deve essere proiettata senza verifica su ogni periodo della storia egiziana. Il dono a Beniamino e l’ordine dei fratelli intensificano la prova delle loro reazioni verso il figlio favorito di Rachele.',formation:'Giuda sostituisce Ruben come garante efficace di Beniamino, preparando il suo discorso in Gen 44. Il capitolo sviluppa motivi già introdotti: denaro restituito, timore davanti al governatore, Simeone e il padre anziano. Le oscillazioni fra Ruben e Giuda appartengono alla discussione sulla composizione della storia di Giuseppe, ma la redazione finale le trasforma anche in caratterizzazione progressiva.',textual:'Il testo è nel complesso stabile. In 43,32 la motivazione della separazione a tavola è formulata come “abominio” per gli Egiziani, termine forte che ricorre anche nel ciclo dell’Esodo; la sua portata storica precisa resta incerta. Le versioni mantengono il motivo. I doni e le porzioni presentano variazioni numeriche minori.',bibliography:[W2,WEST3,H2,SARNA]},
44:{context:'La coppa d’argento funziona come oggetto di prova e come simbolo dell’autorità di Giuseppe. Il riferimento alla divinazione mediante coppa riflette pratiche note nel mondo antico, ma il narratore non afferma necessariamente che Giuseppe dipenda realmente da tale tecnica: altrove le interpretazioni sono attribuite a Dio. Il centro etico del capitolo è la disponibilità di Giuda a sostituirsi a Beniamino.',formation:'La costruzione ripete deliberatamente la situazione di Gen 37: un figlio di Rachele rischia di essere perduto e i fratelli devono scegliere come reagire. Il lungo discorso di Giuda ricapitola la vicenda dal punto di vista del padre e rappresenta il culmine retorico prima della rivelazione. La coerenza narrativa sostiene la lettura della storia di Giuseppe come composizione fortemente elaborata, pur con strati precedenti.',textual:'In 44,5 e 44,15 il verbo relativo alla divinazione è chiaro, ma il suo valore nella caratterizzazione di Giuseppe resta esegetico. Il discorso di Giuda contiene riprese e adattamenti di dialoghi precedenti: le differenze non sono necessariamente corruzioni testuali, ma possono essere retorica narrativa. Le versioni concordano nella sostanza dell’offerta sostitutiva di Giuda.',bibliography:[W2,WEST3,H2,SCHMID]},
45:{context:'La rivelazione di Giuseppe trasforma una vicenda familiare in migrazione collettiva verso l’Egitto. L’invito del faraone e l’insediamento nel Delta appartengono alla geografia narrativa che preparerà Esodo. La lettura provvidenziale di Giuseppe non elimina la responsabilità dei fratelli: il testo tiene insieme intenzione umana negativa e capacità divina di produrre salvezza.',formation:'Gen 45 risolve il dispositivo del riconoscimento differito. Il discorso di Giuseppe interpreta retrospettivamente l’intera trama (“Dio mi ha mandato davanti a voi”), tema che culminerà in 50,20. La presenza del faraone e dell’invito ufficiale collega la riconciliazione familiare alla successiva discesa di Giacobbe. Le ripetizioni teologiche possono riflettere elaborazione redazionale, ma sono integrate nel climax.',textual:'Le principali varianti riguardano dettagli del discorso e dei doni. In 45,8 la triplice descrizione di Giuseppe come padre del faraone, signore della casa e governatore usa titoli retorici, non una titolatura amministrativa da identificare direttamente con un ufficio egiziano documentato. La LXX presenta occasionali condensazioni tipiche della sua resa della Genesi.',bibliography:[W2,WEST3,H2,SARNA]},
46:{context:'La sosta a Bersabea collega Giacobbe ai luoghi cultuali di Abramo e Isacco prima della discesa in Egitto. La lista dei discendenti trasforma una famiglia in embrione del popolo d’Israele. I numeri genealogici non vanno letti come censimento moderno: servono anche a esprimere totalità e continuità, e le tradizioni testuali non concordano sul totale.',formation:'46,1–7 offre una teofania che rassicura Giacobbe: scendere in Egitto non annulla la promessa. 46,8–27 è una genealogia di profilo sacerdotale, integrata nella narrazione. 46,28–34 riprende la prosa della storia di Giuseppe e prepara l’incontro con il faraone. Il capitolo è quindi un esempio chiaro di coordinamento fra generi e strati differenti.',textual:'Il totale dei membri è uno dei casi più importanti della critica testuale della Genesi: MT arriva a settanta, mentre la LXX include ulteriori discendenti di Giuseppe e sostiene il numero settantacinque ripreso in At 7,14. Qumran offre dati rilevanti per la pluralità delle liste. Non è corretto “correggere” una tradizione con l’altra: rappresentano forme genealogiche differenti.',bibliography:[W2,WEST3,H2,SARNA]},
47:{context:'L’insediamento in Gosen/Ramesse e la politica di Giuseppe durante la carestia introducono temi economici e territoriali. La concentrazione di terra e lavoro sotto il faraone corrisponde a un’immagine di forte centralizzazione monarchica, ma non è possibile collegarla a una singola riforma storica nota. Il toponimo Ramesse è significativo per la memoria egiziana del Pentateuco, non una datazione automatica di Giuseppe.',formation:'Il capitolo alterna presentazione della famiglia al faraone, sostentamento dei parenti e politica economica per il resto dell’Egitto. 47,27–31 ritorna a Giacobbe e alla promessa della sepoltura in Canaan, preparando Gen 48–50. Alcuni studiosi distinguono strati nella politica agraria e nelle formule di insediamento, ma la forma finale crea un contrasto fra prosperità d’Israele e dipendenza degli Egiziani.',textual:'In 47,31 il MT può essere vocalizzato come Giacobbe che si prostra “sulla testata del letto”, mentre la LXX legge “sulla cima del bastone”, differenza dovuta alle stesse consonanti e a vocalizzazione diversa; Eb 11,21 segue la forma greca. È un caso esemplare per mostrare come una minima differenza di vocalizzazione produca due immagini entrambe antiche.',bibliography:[W2,WEST3,H2,SARNA]},
48:{context:'L’adozione di Efraim e Manasse spiega la presenza di due tribù giuseppine e la mancanza di una tribù territoriale di Giuseppe come unità semplice. La preferenza di Efraim sul primogenito Manasse riflette la successiva importanza politica di Efraim nel regno del Nord. La scena trasforma dunque una benedizione familiare in eziologia dell’assetto tribale.',formation:'Il capitolo combina memoria sacerdotale della promessa a Luz, adozione dei figli e benedizione narrativa. L’incrocio delle mani riprende il motivo genesiaco del minore che precede il maggiore. La presenza di formule e prospettive differenti ha favorito analisi stratificate, ma il risultato finale lega strettamente promessa ancestrale e geografia tribale d’Israele.',textual:'In 48,22 il termine shekem può significare “spalla/porzione” e richiama anche il toponimo Sichem; la frase sulla conquista con spada e arco è difficile da conciliare con altri racconti e ha generato diverse interpretazioni. Le versioni riflettono l’ambiguità. La benedizione di 48,20 è invece stabile e conserva l’ordine Efraim-Manasse.',bibliography:[W2,WEST3,H2,BLUM]},
49:{context:'I detti sui figli di Giacobbe sono in realtà ritratti poetici di tribù e territori. Giuda, Zabulon, Dan, Giuseppe e gli altri sono descritti con immagini animali, agricole e militari che riflettono memorie politiche diverse. Il poema non appartiene necessariamente a un solo momento storico: può conservare materiali di epoche differenti successivamente raccolti sotto la cornice della benedizione paterna.',formation:'49,1–28 costituisce una raccolta poetica inserita nella conclusione narrativa della vita di Giacobbe; 49,29–33 torna alla prosa e alla sepoltura di Macpela. Il primato di Giuda e l’ampiezza della benedizione di Giuseppe sono centrali per la discussione sulla storia della raccolta. Le attribuzioni cronologiche dei singoli detti restano controverse e devono essere presentate con gradi di certezza.',textual:'Il testo poetico di Gen 49 contiene numerosi hapax, forme arcaizzanti e passi oscuri. 49,10 (“scettro… Shiloh/colui al quale appartiene”) è uno dei loci più discussi: MT, LXX e interpretazioni antiche divergono nella comprensione. Anche 49,5–6 e 49,21 presentano difficoltà. Qui la critica testuale deve accompagnare ogni traduzione con particolare cautela.',bibliography:[W2,WEST3,H2,SARNA]},
50:{context:'Imbalsamazione, lutto e corteo funebre rafforzano l’ambientazione egiziana, mentre la sepoltura di Giacobbe a Macpela riafferma il legame con Canaan. Giuseppe stesso viene imbalsamato ma resta in una bara in Egitto: la conclusione è deliberatamente aperta. La famiglia è salva, ma fuori dalla terra; la promessa del ritorno collega Genesi alla futura narrazione dell’Esodo.',formation:'Il capitolo chiude simultaneamente la storia di Giacobbe, la riconciliazione dei fratelli e l’intera Genesi. 50,15–21 formula la teologia narrativa della provvidenza: il male progettato dagli uomini può essere orientato da Dio alla vita. 50,24–26 crea un ponte letterario verso Esodo attraverso la promessa della visita divina e delle ossa di Giuseppe. La connessione Genesi–Mosè è quindi redazionalmente esplicita.',textual:'In 50,20 il contrasto fra il “pensare/progettare” il male dei fratelli e il “progettare” di Dio il bene usa lo stesso verbo ebraico, dato essenziale che alcune traduzioni attenuano. Le età e i dettagli funerari sono sostanzialmente stabili. La LXX presenta differenze locali, ma conserva sia la teologia di 50,20 sia l’attesa del ritorno finale.',bibliography:[W2,WEST3,H2,SCHMID]}
};
